let pos = 0;
const n = Number(data[pos++]);

const left = [0];
const right = [0];
const size = [0];
const count = [0];
const key = [0];
const priority = [0];

let seed = 123456789;
function randomPriority() {
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  return seed >>> 0;
}

function nodeSize(node) {
  return node === 0 ? 0 : size[node];
}

function rotateRight(root) {
  const child = left[root];
  left[root] = right[child];
  right[child] = root;
  size[root] = count[root] + nodeSize(left[root]) + nodeSize(right[root]);
  size[child] = count[child] + nodeSize(left[child]) + nodeSize(right[child]);
  return child;
}

function rotateLeft(root) {
  const child = right[root];
  right[root] = left[child];
  left[child] = root;
  size[root] = count[root] + nodeSize(left[root]) + nodeSize(right[root]);
  size[child] = count[child] + nodeSize(left[child]) + nodeSize(right[child]);
  return child;
}

function insert(root, value) {
  if (root === 0) {
    const id = key.length;
