    left.push(0);
    right.push(0);
    count.push(1);
    size.push(1);
    priority.push(randomPriority());
    return id;
  }

  if (value === key[root]) {
    count[root]++;
  } else if (value < key[root]) {
    left[root] = insert(left[root], value);
    if (priority[left[root]] > priority[root]) root = rotateRight(root);
