    right[root] = insert(right[root], value);
    if (priority[right[root]] > priority[root]) root = rotateLeft(root);
  }

  size[root] = count[root] + nodeSize(left[root]) + nodeSize(right[root]);
  return root;
}

function countAtMost(root, value) {
  let result = 0;
  while (root !== 0) {
    if (value < key[root]) {
      root = left[root];
    } else {
      result += nodeSize(left[root]) + count[root];
      root = right[root];
    }
  }
  return result;
}

let root = 0;
let previousPenalty = 0;
const output = [];

for (let i = 0; i < n; i++) {
  const x = Number(data[pos++]) + previousPenalty;
  const y = Number(data[pos++]) + previousPenalty;
  const distanceSquared = x * x + y * y;

  const penalty = countAtMost(root, distanceSquared);
